const _raw = $('POST /generate/orchestrated').item.json.body || {};
const body = (() => {
  const keys = Object.keys(_raw);
  if (keys.length === 1 && String(keys[0]).trimStart().startsWith('{')) {
    try { return JSON.parse(keys[0]); } catch (_) {}
  }
  return _raw;
})();
const user_id    = $json.user_id;
const upload_id  = (body.upload_id  || '').toString().trim();
const brief      = (body.brief      || '').toString().trim();
const session_id = body.session_id  ? body.session_id.toString() : null;
const room_hint  = body.room_type   ? body.room_type.toString().trim() : null;
const style_tag  = body.style_tag   ? body.style_tag.toString().trim() : null;

const missing = [];
if (!upload_id) missing.push('upload_id');
if (!brief)     missing.push('brief');
if (missing.length) {
  return [{ json: { _error: { status: 400, body: { error: `missing_fields: ${missing.join(',')}`, code: 'invalid_request' } } } }];
}

const storage_path = `user-uploads/${user_id}/${upload_id}`;
const upload_url   = `https://uzghfpxboktnbcbbthns.supabase.co/storage/v1/object/public/${storage_path}`;
return [{ json: { user_id, upload_id, brief, session_id, room_hint, style_tag, upload_url, started_at_ms: Date.now() } }];

const ctx = $input.item.json;
const arrayBuf = await this.helpers.httpRequest({
  method: 'GET',
  url: ctx.upload_url,
  encoding: 'arraybuffer',
});
const b64 = Buffer.from(arrayBuf).toString('base64');
const mime = 'image/jpeg';
return [{ json: { ...ctx, upload_b64: b64, upload_mime: mime } }];

const ctx  = $input.item.json;
const b64  = ctx.upload_b64;
const mime = ctx.upload_mime || 'image/jpeg';
const dataUri = `data:${mime};base64,${b64}`;

const styleContext = ctx.style_tag
  ? `The user has selected style: "${ctx.style_tag}". Use this as the primary style direction.`
  : 'No style was pre-selected. Infer the best style from the user brief and room photo.';

const SYSTEM = `You are an interior-design reference retrieval and prompt-orchestration agent for Nano Banana 2.

Your mission: given a user\'s design brief, a style selection (if provided), and a photograph of the actual room, you must:
1. Interpret every usable specification in the brief.
2. Critically reason about the room\'s 3D spatial structure as visible in the photograph — wall positions visible, perceived depth, ceiling height, window placement and size, natural light direction, focal wall.
3. Write retrieval criteria that the NEXT AGENT will use to pick exactly 3 reference images from the database.
4. Write one curated Nano Banana 2 generation prompt.

${styleContext}

Output format — STRICT. No preamble. No code fences. Exactly two delimited blocks:

===CRITERIA===
Room type:
<state the room type explicitly>

3D spatial structure (grounded in photo):
<Precise observations: number of walls visible, room depth, ceiling height (low/standard/high/vaulted), window wall position (left/right/back/front/multiple), natural light direction and intensity, floor coverage visible>

Style intent:
<Target aesthetic, material palette, colour story — use selected style if provided>

Daylight & ambience:
<Lighting mood, warmth, time-of-day feel desired in the output>

Functional requirements:
<Furniture types, zones, layout priorities>

Complementarity guidance:
Reference 1 must match the 3D spatial geometry: similar room proportions, ceiling height, and window placement.
Reference 2 must match the style, materials, and colour palette.
Reference 3 must match the lighting quality and ambience.
===END===

===PROMPT===
<One polished Nano Banana 2 creative brief in natural sentences. Must: (a) instruct to preserve the exact room geometry shown in the first input image — walls, windows, ceiling; (b) apply style \'${ctx.style_tag || 'as derived from brief'}\'; (c) describe the desired furnishing, materials, palette, and lighting. No keyword soup. No people, no text, no logos.>
===END===`;

const openrouter_body = {
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user', content: [
      { type: 'text', text: `User brief:\n${ctx.brief}\n\n${ctx.style_tag ? `Selected style: ${ctx.style_tag}\n\n` : ''}Room type hint: ${ctx.room_hint || '(infer from photo)'}\n\nRoom photograph attached. Ground ALL 3D spatial reasoning in this image — do not assume, only observe.` },
      { type: 'image_url', image_url: { url: dataUri } }
    ]}
  ],
  temperature: 0.4,
  max_tokens: 2048
};

return [{ json: { ...ctx, openrouter_body } }];

const ctx     = $('Build Agent 1 request').item.json;
const resp    = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
if (!content) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_empty_response', code: 'upstream_error' } } } }];
}

function extractBlock(text, startTag) {
  const startRe = new RegExp(`={3,}\\s*${startTag}\\s*={3,}`, 'i');
  const endRe   = /={3,}\s*END\s*={3,}/i;
  const s = text.search(startRe);
  if (s < 0) return null;
  const after = text.slice(s).replace(startRe, '');
  const e = after.search(endRe);
  if (e < 0) return after.trim();
  return after.slice(0, e).trim();
}

const criteria = extractBlock(content, 'CRITERIA');
const prompt   = extractBlock(content, 'PROMPT');
if (!criteria || !prompt) {
  return [{ json: { _error: { status: 502, body: { error: 'agent1_bad_format', code: 'upstream_error', raw: content.slice(0, 500) } } } }];
}

const roomWords = ['bedroom','living room','kitchen','dining room','bathroom','office','study room','kids room','nursery','hallway','entryway','mandir'];
const lc = (criteria + ' ' + (ctx.brief || '') + ' ' + (ctx.room_hint || '')).toLowerCase();
let inferred_room = ctx.room_hint || null;
if (!inferred_room) {
  for (const w of roomWords) { if (lc.includes(w)) { inferred_room = w; break; } }
}

const ftsTerms = [ctx.brief, ctx.style_tag, inferred_room].filter(Boolean).join(' ');

return [{ json: { ...ctx, criteria, agent_prompt: prompt, inferred_room, fts_search_text: ftsTerms } }];

const rows = Array.isArray($json) ? $json : ($json.body || []);
const ctx  = $('Parse Agent 1').item.json;
if (rows.length >= 3) {
  return [{ json: { ...ctx, pool: rows, pool_fallback: false } }];
}
return [{ json: { ...ctx, pool: rows, pool_fallback: true } }];

const rows = Array.isArray($json) ? $json : ($json.body || []);
const ctx  = $('Check pool').item.json;
return [{ json: { ...ctx, pool: rows } }];

const ctx  = $json;
const pool = ctx.pool || [];
if (pool.length < 3) {
  return [{ json: { _error: { status: 500, body: { error: 'pool_too_small', code: 'internal_error', count: pool.length } } } }];
}

const SYSTEM = `You are a spatial-aware reference-image selector for an interior design AI pipeline.

You receive:
1. A CRITERIA block from a design director, including 3D spatial structure observations of the user\'s room.
2. A pool of candidate reference images, each shown as a card.

Card format:
[id=<uuid>] <enhanced caption or fallback caption>
  spatial: shape=<room_shape> depth=<depth_cues> ceil=<ceiling_height> win=<window_wall> light=<light_direction> sym=<symmetry>
  style:[<tags>] colors:[<hex>] room:<room_type>

Your task: Pick exactly 3 reference IDs whose COMBINED coverage best satisfies the criteria.

PICKING RULES (in priority order):
Reference 1 — SPATIAL MATCH: must have the closest 3D geometry to the user\'s room.
  Look for: same ceiling_height, same window_wall position, similar depth_cues, similar room_shape.
Reference 2 — STYLE MATCH: must best represent the target style, materials, and colour palette.
Reference 3 — AMBIENCE MATCH: must best represent the target lighting quality and mood.

Constraints: complementary picks only (not redundant). Never invent IDs. Never repeat IDs.

Output — STRICT. Exactly three lines, nothing else:
Reference 1: <uuid> — <one sentence: which spatial feature matched>
Reference 2: <uuid> — <one sentence: which style/material matched>
Reference 3: <uuid> — <one sentence: which lighting/ambience matched>`;

const cards = pool.map(r => {
  const style   = Array.isArray(r.style_tags) ? r.style_tags.join(',') : '';
  const colors  = Array.isArray(r.dominant_colors) ? r.dominant_colors.join(',') : '';
  const cap     = (r.caption_enhanced || r.caption || '').replace(/\s+/g, ' ').trim().slice(0, 200);

  let spatialLine = '';
  const s = r.spatial_sig || r.spatial_signature;
  if (s && typeof s === 'object') {
    spatialLine = `\n  spatial: shape=${s.room_shape||'?'} depth=${s.depth_cues||'?'} ceil=${s.ceiling_height||'?'} win=${s.window_wall||'?'} light=${s.light_direction||'?'} sym=${s.symmetry||'?'}`;
  }

  return `[id=${r.id}] ${cap}${spatialLine}\n  style:[${style}] colors:[${colors}] room:${r.room_type||'?'}`;
}).join('\n\n');

const user = `===CRITERIA===\n${ctx.criteria}\n===END===\n\n===CANDIDATES===\n${cards}\n===END===`;

const openrouter_body = {
  model: 'google/gemini-2.5-flash',
  messages: [
    { role: 'system', content: SYSTEM },
    { role: 'user',   content: user }
  ],
  temperature: 0.2,
  max_tokens: 512
};

return [{ json: { ...ctx, openrouter_body } }];

const ctx  = $('Build Agent 2 request').item.json;
const resp = $json;
const content = (resp.choices && resp.choices[0] && resp.choices[0].message && resp.choices[0].message.content) || '';
const uuidRe = /[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/gi;
const matches = (content.match(uuidRe) || []).map(s => s.toLowerCase());

const poolIds = new Set((ctx.pool || []).map(r => r.id.toString().toLowerCase()));
const seen = new Set();
const picks = [];
for (const m of matches) {
  if (!poolIds.has(m)) continue;
  if (seen.has(m)) continue;
  seen.add(m);
  picks.push(m);
  if (picks.length === 3) break;
}

if (picks.length < 3) {
  const sorted = [...(ctx.pool || [])].sort((a, b) => (b.quality_score || 0) - (a.quality_score || 0));
  for (const r of sorted) {
    const id = r.id.toString().toLowerCase();
    if (seen.has(id)) continue;
    seen.add(id);
    picks.push(id);
    if (picks.length === 3) break;
  }
}

if (picks.length < 3) {
  return [{ json: { _error: { status: 500, body: { error: 'retriever_picks_too_few', code: 'internal_error' } } } }];
}

return [{ json: { ...ctx, picked_reference_ids: picks } }];

const ctx  = $('Parse Agent 2').item.json;
const refs = Array.isArray($json) ? $json : ($json.body || []);
const byId = {};
refs.forEach(r => { byId[r.id.toString().toLowerCase()] = r.source_url; });

const urls = [ctx.upload_url];
for (const id of ctx.picked_reference_ids) {
  if (byId[id]) urls.push(byId[id]);
}
if (urls.length !== 4) {
  return [{ json: { _error: { status: 500, body: { error: 'picked_reference_url_missing', code: 'internal_error' } } } }];
}
return urls.map((url, i) => ({ json: { ...ctx, idx: i, fetch_url: url } }));

const items = $input.all();
items.sort((a, b) => a.json.idx - b.json.idx);
const parts = items.map(it => ({
  inline_data: {
    mime_type: it.binary.image.mimeType || 'image/png',
    data:      it.binary.image.data
  }
}));
return [{ json: { ...items[0].json, image_parts: parts } }];

const rows  = Array.isArray($json) ? $json : ($json.body || []);
const model = (rows[0] && rows[0].value) || 'gemini-3.1-flash-image-preview';
const ctx   = $('Collect image parts').item.json;

const gemini_body = {
  contents: [{
    role: 'user',
    parts: [ { text: ctx.agent_prompt }, ...ctx.image_parts ]
  }],
  generationConfig: { responseModalities: ['IMAGE'] }
};

return [{ json: { ...ctx, model, gemini_body } }];

const ctx  = $('Build Gemini request').item.json;
const resp = $json;
const parts = (resp.candidates && resp.candidates[0] && resp.candidates[0].content && resp.candidates[0].content.parts) || [];
const imgPart = parts.find(p => p.inlineData || p.inline_data);
if (!imgPart) {
  return [{ json: { _error: { status: 502, body: { error: 'no_image_in_response', code: 'upstream_error' } } } }];
}
const inline = imgPart.inlineData || imgPart.inline_data;
const b64    = inline.data;
const mime   = inline.mimeType || inline.mime_type || 'image/png';
const latency_ms = Date.now() - ctx.started_at_ms;

return [{
  json: {
    user_id:              ctx.user_id,
    session_id:           ctx.session_id,
    parent_generation_id: null,
    kind:                 'orchestrated',
    input_image_path:     `user-uploads/${ctx.user_id}/${ctx.upload_id}`,
    room_type:            ctx.inferred_room || null,
    style_tag:            ctx.style_tag || null,
    reference_image_ids:  ctx.picked_reference_ids,
    prompt:               ctx.agent_prompt,
    criteria:             ctx.criteria,
    model_config:         'A',
    model_id:             ctx.model,
    latency_ms,
    cost_usd:             0
  },
  binary: { output_png: { data: b64, mimeType: mime, fileExtension: 'png', fileName: 'output.png' } }
}];

parameters.responseBody:
={{ JSON.stringify({
  generation_id:       $json.generation_id,
  output_url:          $json.output_url,
  latency_ms:          $json.latency_ms,
  cost_usd:            $json.cost_usd,
  model_id:            $json.model_id,
  backend_id:          'gemini',
  reference_image_ids: $('Parse Agent 2').item.json.picked_reference_ids,
  criteria:            $('Parse Agent 1').item.json.criteria
}) }}
